style.css:
@-moz-document domain("pekora.zip") {
/* Hide the existing PEKORA image/logo */
  img[src*="logo"] {
    display: none !important;
  }

  /* Replace it with a text-based ROBLOX logo */
  .navbar-brand::before {
    content: "ROBLOX";
    font-family: 'Luckiest Guy', 'Arial Black', cursive, sans-serif;
    font-size: 32px;
    color: white;
    display: inline-block;
    margin-left: 10px;
  }

  /* Optional: center or adjust position */
  .navbar-brand {
    background: none !important;
  }
}
